<script lang="ts">
 import {createEventDispatcher} from 'svelte';import {api} from '$lib/api/api';import type {Combatant} from '$lib/types';export let fighter:Combatant;const dispatch=createEventDispatcher();let hidden=fighter.hidden===true;let hideStats=fighter.hideStats===true;let notes=fighter.notes||'';let busy=false;let error='';
 async function save(){busy=true;error='';try{await api.setCombatVisibility(fighter.id,{hidden,hideStats,notes});dispatch('close');}catch(cause){error=cause instanceof Error?cause.message:'No se pudo guardar.';}finally{busy=false;}}
</script>
<div class="modal modal-open z-50" role="dialog" aria-modal="true" aria-label="Preparación privada del combatiente"><div class="card-parchment p-4 border-2 border-secondary w-full max-w-lg max-h-[90dvh] overflow-y-auto text-neutral space-y-3"><h3 class="font-medieval text-xl">{fighter.name} · Preparación del DM</h3><label class="flex items-center gap-2 text-sm"><input class="checkbox checkbox-sm border-neutral/70 text-primary bg-white/30 shrink-0" type="checkbox" bind:checked={hidden}/>Ocultar al combatiente a los jugadores</label><label class="flex items-center gap-2 text-sm"><input class="checkbox checkbox-sm border-neutral/70 text-primary bg-white/30 shrink-0" type="checkbox" bind:checked={hideStats}/>Reservar vida exacta y CA</label><label class="block text-sm">Notas privadas del DM<textarea class="textarea textarea-bordered w-full" maxlength="4000" bind:value={notes}/></label>{#if error}<p role="alert" class="text-error">{error}</p>{/if}<div class="flex gap-2"><button class="btn btn-sm" disabled={busy} on:click={save}>{busy?'Guardando…':'Guardar'}</button><button class="btn btn-sm" disabled={busy} on:click={()=>dispatch('close')}>Cerrar</button></div></div></div>
<style>.textarea{color:#f7ecd8;background:#2d241c;}</style>
